window.ScripturaLexicons.BDAG_PART_0318 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-01\" data-source=\"BDAG\" data-search=\"σάκκος, ου, ὁ substantivo masculino saco, pano de saco BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σάκκος, ου, ὁ</td><td>substantivo masculino</td><td>saco, pano de saco</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-02\" data-source=\"BDAG\" data-search=\"Σαλά, ὁ nome próprio masculino indeclinável Salá BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαλά, ὁ</td><td>nome próprio masculino indeclinável</td><td>Salá</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-03\" data-source=\"BDAG\" data-search=\"Σαλαθιήλ, ὁ nome próprio masculino indeclinável Sealtiel, Salatiel BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαλαθιήλ, ὁ</td><td>nome próprio masculino indeclinável</td><td>Sealtiel, Salatiel</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-04\" data-source=\"BDAG\" data-search=\"Σαλαμίς, ῖνος, ἡ nome próprio feminino Salamina BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαλαμίς, ῖνος, ἡ</td><td>nome próprio feminino</td><td>Salamina</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-05\" data-source=\"BDAG\" data-search=\"Σαλείμ, τό nome próprio neutro indeclinável Salim BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαλείμ, τό</td><td>nome próprio neutro indeclinável</td><td>Salim</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-06\" data-source=\"BDAG\" data-search=\"σαλεύω verbo sacudir, abalar; perturbar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαλεύω</td><td>verbo</td><td>sacudir, abalar; perturbar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-07\" data-source=\"BDAG\" data-search=\"Σαλήμ, ἡ nome próprio feminino Salém BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαλήμ, ἡ</td><td>nome próprio feminino</td><td>Salém</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-08\" data-source=\"BDAG\" data-search=\"Σαλίμ, τό remissão ver Σαλείμ BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαλίμ, τό</td><td>remissão</td><td>ver Σαλείμ</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-09\" data-source=\"BDAG\" data-search=\"Σαλμών, ὁ nome próprio masculino indeclinável Salmom BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαλμών, ὁ</td><td>nome próprio masculino indeclinável</td><td>Salmom</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-10\" data-source=\"BDAG\" data-search=\"Σαλμώνη, ης, ἡ nome próprio feminino Salmone BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαλμώνη, ης, ἡ</td><td>nome próprio feminino</td><td>Salmone</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-11\" data-source=\"BDAG\" data-search=\"σάλος, ου, ὁ substantivo masculino agitação, ondulação, ímpeto das ondas BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σάλος, ου, ὁ</td><td>substantivo masculino</td><td>agitação, ondulação, ímpeto das ondas</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-12\" data-source=\"BDAG\" data-search=\"σάλπιγξ, ιγγος, ἡ substantivo feminino trombeta; toque de trombeta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σάλπιγξ, ιγγος, ἡ</td><td>substantivo feminino</td><td>trombeta; toque de trombeta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-13\" data-source=\"BDAG\" data-search=\"σαλπίζω verbo tocar trombeta; alardear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαλπίζω</td><td>verbo</td><td>tocar trombeta; alardear</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-14\" data-source=\"BDAG\" data-search=\"σαλπιστής, οῦ, ὁ substantivo masculino trombeteiro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">σαλπιστής, οῦ, ὁ</td><td>substantivo masculino</td><td>trombeteiro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-15\" data-source=\"BDAG\" data-search=\"Σαλώμη, ης, ἡ nome próprio feminino Salomé BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαλώμη, ης, ἡ</td><td>nome próprio feminino</td><td>Salomé</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-16\" data-source=\"BDAG\" data-search=\"Σαλωμών variante de nome próprio ver Σολομών BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαλωμών</td><td>variante de nome próprio</td><td>ver Σολομών</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-17\" data-source=\"BDAG\" data-search=\"Σαμάρεια, ας, ἡ nome próprio feminino Samaria BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαμάρεια, ας, ἡ</td><td>nome próprio feminino</td><td>Samaria</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-18\" data-source=\"BDAG\" data-search=\"Σαμαρία remissão ver Σαμάρεια BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαμαρία</td><td>remissão</td><td>ver Σαμάρεια</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-19\" data-source=\"BDAG\" data-search=\"Σαμαρίτης, ου, ὁ substantivo masculino samaritano BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαμαρίτης, ου, ὁ</td><td>substantivo masculino</td><td>samaritano</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0318-20\" data-source=\"BDAG\" data-search=\"Σαμαρῖτις, ιδος, ἡ adjetivo e substantivo feminino samaritana BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Σαμαρῖτις, ιδος, ἡ</td><td>adjetivo e substantivo feminino</td><td>samaritana</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0318-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάκκος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σάκκος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hdt., Aristoph.+; inscr., pap., LXX; PsSol 20:2; Test12Patr, JosAs; AscIs 2:10; Joseph.; Mel., P. 19, 131.—Empréstimo semítico: HLewy, Die semit. Lehnwörter im Griech. 1895, 87 [cf. <span class=\"hebrew\">שַׂק</span>]. Sobre a questão de grafá-lo com um <span class=\"greek\">κ</span> ou dois, v. Mayser 215) tecido grosseiro feito de pelo de animal (cabra ou camelo), saco, pano de saco <span class=\"greek\">ὠμόλινον</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">σάκκου</span> <span class=\"greek\">γεγονός</span> uma toalha áspera de linho feita de (um) saco (pano de saco) Hs 8, 4, 1. O tecido de que se faz um saco é usualmente de cor escura <span class=\"greek\">ἁμαρτίαι</span> <span class=\"greek\">μελανώτεραι</span> <span class=\"greek\">σάκκου</span> 1 Cl 8:3 (citação de origem desconhecida). <span class=\"greek\">μέλας</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">σάκκος</span> <span class=\"greek\">τρίχινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:12</a> (cf. Is 50:3). Por isso o pano de saco é especialmente apropriado para ser usado como veste de luto (LXX; PsSol 2:20; JosAs 10:16 al.; Jos., Bell. 2, 237, Ant. 5, 37 al.) <span class=\"greek\">περιβεβλημένοι</span> <span class=\"greek\">σάκκους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:3</a> (cf. 4 Km 19:2; Is 37:2; AscIs 2:10 <span class=\"greek\">σάκκον</span> e v. <span class=\"greek\">περιβάλλω</span> 2a). <span class=\"greek\">ἔρριψεν</span> <span class=\"greek\">αὑτὸν</span> <span class=\"greek\">χαμαὶ</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">ς</span>. (José) lançou-se ao chão sobre pano de saco JosAs 13:1. Com <span class=\"greek\">σποδός</span> (Esth 4:2f; Jos., Ant. 20, 123; TestJos 15:2) <span class=\"greek\">ἐν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">σποδῷ</span> <span class=\"greek\">καθῆσθαι</span> sentar-se em pano de saco e cinzas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:13</a> (Mel., P. 19, 131). <span class=\"greek\">ἐν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">σποδῷ</span> <span class=\"greek\">μετανοεῖν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:21</a>. <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">ς</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">σποδοῦ</span> <span class=\"greek\">κόπτεσθαι</span> (<span class=\"greek\">κόπτω</span> 2) B 7:5. <span class=\"greek\">καὶ</span> <span class=\"greek\">σάκκον</span> <span class=\"greek\">ἐνδύσησθε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σποδὸν</span> <span class=\"greek\">ὑποστρώσητε</span> 3:2 (Is 58:5).—Menand., Fgm. 544 Kock=754 Kö., a respeito de penitentes sírios que haviam pecado contra a deusa: <span class=\"greek\">ἔλαβον</span> <span class=\"greek\">σακίον</span>, <span class=\"greek\">εἶτ</span>’ <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ὁδὸν</span> <span class=\"greek\">ἐκάθισαν</span> <span class=\"greek\">αὑτοὺς</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">κόπρου</span>, <span class=\"greek\">καὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ἐξιλάσαντο</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ταπεινοῦσθαι</span> <span class=\"greek\">σφόδρα</span> ‘tomaram pano de saco, depois sentaram-se no caminho sobre um monturo e apaziguaram a deusa humilhando-se sobremaneira’; Plut., Superst. 7 p. 168d: <span class=\"greek\">ἔξω</span> <span class=\"greek\">κάθηται</span> <span class=\"greek\">σακκίον</span> <span class=\"greek\">ἔχων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">περιεζωσμένος</span> <span class=\"greek\">ῥάκεσι</span> <span class=\"greek\">ῥυπαροῖς</span>, <span class=\"greek\">πολλάκις</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">γυμνὸς</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πηλῷ</span> <span class=\"greek\">κυλινδούμενος</span> <span class=\"greek\">ἐξαγορεύει</span> <span class=\"greek\">τινὰς</span> <span class=\"greek\">ἁμαρτίας</span>, <span class=\"greek\">ὡς</span> <span class=\"greek\">τόδε</span> <span class=\"greek\">φαγόντος</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">πιόντος</span> <span class=\"greek\">ἢ</span> <span class=\"greek\">βαδίσαντος</span> <span class=\"greek\">ὁδόν</span>, <span class=\"greek\">ἣν</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">εἴα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δαιμόνιον</span> ‘senta-se do lado de fora em pano de saco, cingido de trapos imundos, e frequentemente rola nu na lama e confessa publicamente alguns pecados, como comer ou beber isto ou aquilo, ou tomar algum caminho proibido pelo Céu’; cf. Lam. 4:5. Sobre os trapos de um penitente cf. <span class=\"greek\">ἐν</span> <span class=\"greek\">ἱεροῖς</span> <span class=\"greek\">ῥακενδύτας</span>: Hermes Trismeg., Cat. Cod. Astr. VIII/4 p. 148, 2; 165, 16.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλά, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαλά</span>, <span class=\"greek\">ὁ</span> (<span class=\"hebrew\">שֶׁלַח</span>) indecl. Salá, na genealogia de Jesus em Lucas.</p><p class=\"entry-text\">① filho de Naassom e pai de Boaz <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:32</a>; aqui a v.l. apresenta <span class=\"greek\">Σαλμών</span> (<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:4</a>f; 1 Ch 2:11; cf. Ruth 4:20f), materialmente correta, mas comprovadamente secundária.—EbNestle, Sala, Salma, Salmon: ZNW 11, 1910, 242f.</p><p class=\"entry-text\">② filho de Cainã e pai de Héber (Gen 10:24; 11:13–15; 1 Ch 1:18 A) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:35</a>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλαθιήλ, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαλαθιήλ</span>, <span class=\"greek\">ὁ</span> (<span class=\"hebrew\">שְׁאַלְתִּיאֵל</span>) indecl. (LXX; ViZech 3 [p. 88, 6 Sch].—Jos., Ant. 11, 73 <span class=\"greek\">Σαλαθίηλος</span>) Sealtiel, Salatiel, pai de Zorobabel (1 Ch 3:19; 2 Esdr 3:2; 5:2; 22:1; Hg 1:1); na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:12</a> é filho de Jeconias (1 Ch 3:17); em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:27</a>, filho de Neri.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλαμίς, ῖνος, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαλαμίς</span>, <span class=\"greek\">ῖνος</span>, <span class=\"greek\">ἡ</span> (sobre a v.l. <span class=\"greek\">Σαλαμίνῃ</span> v. B-D-F §57; Mlt-H. 128) Salamina, grande cidade na costa oriental da ilha de Chipre (Aeschyl., Hdt. et al.; inscr.; SibOr 4, 128; 5, 452 <span class=\"greek\">πόλις</span> <span class=\"greek\">μεγάλη</span>), visitada por Paulo em sua ‘primeira’ viagem missionária <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:5</a>.—V. a lit. sobre <span class=\"greek\">Κύπρος</span>.—Pauly-W. II 1832–44; Kl. Pauly IV 1505f; BHHW III 1645f; PECS 794–96.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλείμ, τό</h1><div class=\"entry-meta\"><span>nome próprio neutro indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαλείμ</span>, <span class=\"greek\">τό</span> (também <span class=\"greek\">Σαλίμ</span>) indecl. Salim. João batizava <span class=\"greek\">ἐν</span> <span class=\"greek\">Αἰνὼν</span> <span class=\"greek\">ἐγγὺς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Σαλίμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.3.23\" target=\"_blank\" rel=\"noopener noreferrer\">J 3:23</a>. Segundo Eus., Onom. p. 40, 1, esse lugar ficava 8 milhas romanas (=12,4 km) ao sul de Citópolis, no norte da Samaria (assim Lagrange e Abel; v. <span class=\"greek\">Αἰνών</span>). Hoje existe um lugar chamado Salim a 5,5 km a leste de Siquém; é mencionado em Epiph., Haer. 55, 2 (este é o preferido por WAlbright, HTR 17, 1924, 193f). V. adicionalmente, para <span class=\"greek\">Αἰνών</span>, também EbNestle, ZDPV 30, 1907, 210ff; BBacon, Biblical World 33, 1909, 223ff; KKundsin, Topolog. Überlieferungsstoffe im J 1925. Erbes s.v. <span class=\"greek\">Βηθανία</span> 2.—BHHW III 1648ff.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαλεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαλεύω</span> fut. 3ª pess. sing. <span class=\"greek\">σαλεύσει</span> Wsd 4:19; 1 aor. <span class=\"greek\">ἐσάλευσα</span>. Pass.: 1 fut. <span class=\"greek\">σαλευθήσομαι</span> Wsd 4:19; 1 aor. <span class=\"greek\">ἐσαλεύθην</span>; perf. 3ª pess. sing. <span class=\"greek\">σεσάλευται</span> Ps 93:18; part. <span class=\"greek\">σεσαλευμένος</span> (<span class=\"greek\">σάλος</span>; Aeschyl., Pla., X.+; OGI 515, 47; pap., LXX; En 101:4; TestSol; TestLevi 3:9; GrBar 6:13; Philo; Jos., Bell. 2, 636, Ant. 8, 136 al.; SibOr 3, 675) prim. ‘sacudir’; em nossa lit. somente trans.</p><p class=\"entry-text\">① fazer mover de um lado para outro, sacudir, fazer oscilar/vacilar; pass. ser sacudido, ser levado a oscilar/vacilar (Diod S 12, 47, 2 <span class=\"greek\">τ</span>. <span class=\"greek\">τείχη</span>) <span class=\"greek\">οἰκίαν</span> sacudir uma casa (uma inundação: Sb 8267, 8 [5 a.C.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.48\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:48</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.26\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:26</a>—Pass. (Hippol., Ref. 1, 8, 12) <span class=\"greek\">κάλαμος</span> <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">ἀνέμου</span> <span class=\"greek\">σαλευόμενος</span> um caniço agitado de um lado para outro pelo vento (Appian, Bell. Civ. 4, 28 §120 [pass. em sentido ativo, a respeito de um caniço oscilante]; v. Is 7:2; Jos., Ant. 4, 51 <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀνέμου</span> <span class=\"greek\">σαλευόμενον</span> <span class=\"greek\">κῦμα</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:24</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.13\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:13</a> v.l. A respeito de uma casa <span class=\"greek\">ἐσαλεύθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τόπος</span> o lugar tremeu, lit. foi abalado (cf. Ps 17:8; GrBar 6:13) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.31\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:31</a> (cf. Lucian, Necyom. 10 <span class=\"greek\">ἅπαντα</span> <span class=\"greek\">ἐκεῖνα</span> <span class=\"greek\">ἐσαλεύετο</span>.—<span class=\"greek\">σαλεύεσθαι</span> como sinal da presença divina TestLevi 3:9; Jos., Ant. 7, 76f). A respeito de alicerces que tremem em um terremoto (cf. Ps 81:5) 16:26. <span class=\"greek\">αἱ</span> <span class=\"greek\">δυνάμεις</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">οὐρανῶν</span> <span class=\"greek\">σαλευθήσονται</span> os exércitos celestes serão abalados <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.29\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:29</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:26</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:25</a> (PJoüon, RSR 29, ’39, 114f). Também a respeito dos céus que se movem ordenadamente por ordem de Deus, provavelmente em referência à variedade de movimentos manifestados nos céus <span class=\"greek\">οἱ</span> <span class=\"greek\">οὐρανοὶ</span> <span class=\"greek\">σαλευόμενοι</span> 1 Cl 20:1 (v. HHellfritz, VigChr 22, ’68, 1–7).—<span class=\"greek\">μέτρον</span> <span class=\"greek\">σεσαλευμένον</span> uma medida cujo conteúdo foi acomodado por agitação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 6:38</a>.—Em linguagem figurada: <span class=\"greek\">τὰ</span> <span class=\"greek\">σαλευόμενα</span> aquilo que é ou pode ser abalado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:27</a>a forma um contraste (cf. Philo, Leg. All. 38) com <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">σαλευόμενα</span> aquilo que não é (nem pode ser) abalado v. 27b; o primeiro é o céu e a terra do mundo tal como agora existe (v. 26), o segundo, o Reino vindouro (v. 28).</p><p class=\"entry-text\">② perturbar interiormente, perturbar, abalar, extensão fig. de 1 (Appian, Iber. 102 §442 a respeito de vacilação na lealdade; PsSol 8:33; 15:4) <span class=\"greek\">ἵνα</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">σαλευθῶ</span> para que eu não seja abalado ou perturbado <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:25</a> (Ps 15:8); <span class=\"greek\">σαλευθῆναι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">νοός</span> (Theodor. Prodr. 4, 319 H. <span class=\"greek\">τὸν</span> <span class=\"greek\">νοῦν</span> <span class=\"greek\">σαλευθείς</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.2.2\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 2:2</a>. Incitar, talvez até o ponto de tumulto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:13</a>.—B. 675. DELG s.v. <span class=\"greek\">σάλος</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλήμ, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαλήμ</span>, <span class=\"greek\">ἡ</span> (<span class=\"hebrew\">שָׁלֵם</span>; LXX; Philo.—Jos., Ant, 1, 180 tem <span class=\"greek\">Σολυμᾶ</span>, também indecl.) Salém. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:1</a>f, seguindo Gen 14:18, chama Melquisedeque <span class=\"greek\">βασιλεὺς</span> <span class=\"greek\">Σαλήμ</span> e interpreta isso como ‘Rei de paz’ (v. Philo, Leg. All. 3, 79 <span class=\"greek\">Μελχισεδὲκ</span> <span class=\"greek\">βασιλέα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">εἰρήνης</span>—<span class=\"greek\">Σαλὴμ</span> <span class=\"greek\">τοῦτο</span> <span class=\"greek\">γὰρ</span> <span class=\"greek\">ἑρμηνεύεται</span>).—V. sobre <span class=\"greek\">Μελχισέδεκ</span> e Erbes s.v. <span class=\"greek\">Βηθανία</span> 2.—BHHW III 1647–48.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλίμ, τό</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαλίμ</span>, <span class=\"greek\">τό</span> v. <span class=\"greek\">Σαλείμ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλμών, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαλμών</span>, <span class=\"greek\">ὁ</span> indecl. (<span class=\"hebrew\">שַׂלְמוֹן</span>), Salmom, filho de Naassom e pai de Boaz (1 Ch 2:11; cf. Ruth 4:20f [<span class=\"greek\">Σαλμάν</span>; mas A lê <span class=\"greek\">Σαλμών</span>]), na genealogia de Jesus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.1.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 1:4</a>f, marido de Raabe; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.32\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:32</a> v.l. (v. <span class=\"greek\">Σαλά</span> 1).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλμώνη, ης, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαλμώνη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (esta forma do nome encontra-se somente em nossa passagem. Alhures aparece como <span class=\"greek\">Σαλμώνιον</span>, <span class=\"greek\">Σαμώνιον</span>, <span class=\"greek\">Σαμμώνιον</span>, <span class=\"greek\">Σαλμωνίς</span>; v. os exemplos em JWeiss, RE XI 89, 14ff) Salmone, promontório no extremo nordeste de Creta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:7</a>.—Kl. Pauly IV 1519, 1532f; BHHW III 1650.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάλος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σάλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> movimento de balanço ou agitação, ondulação impetuosa, esp. das ondas em mar revolto (v. <span class=\"greek\">σαλεύω</span>; Trag.; Plut., Lucull. 498 [10, 3]; Lucian, Tox. 19, Hermot. 28; Jon 1:15; Ps 88:10; PsSol 6:3.—Philo, Sacr. Abel. 13 al., metaf. com <span class=\"greek\">κλύδων</span>. Metaf. também Jos., Ant. 14, 376), mas também a respeito de um terremoto (Eur., Iph. Taur. 46; Is 24:20 v.l.; Jos., Ant. 4, 51), embora o primeiro sentido seja mais provável em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:25</a>.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σάλπιγξ, ιγγος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σάλπιγξ</span>, <span class=\"greek\">ιγγος</span>, <span class=\"greek\">ἡ</span> (v. os dois verbetes seguintes; Hom.+; Kaibel 1049, 7; New Docs 4, p. 19, linha 5, em um combate de gladiadores; PHerm 121, 10; LXX; TestAbr A 12 p. 91, 7 [Stone p. 30, 7]; ParJer 3:2; ApcSed; ApcEsdr 4:36 p. 29, 13 Tdf.; ApcMos; Philo; Jos., Bell. 3, 89 (uso militar), Ant. 3, 291, 7, 359; Tat. 1, 2; empréstimo nos escritos rabínicos)</p><p class=\"entry-text\">① instrumento de sopro empregado esp. para comunicação, trombeta (Artem. 1, 56, p. 52, 15ff: a <span class=\"greek\">ἱερὰ</span> <span class=\"greek\">ς</span>. é reta, a trombeta militar é espiralada) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 14:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.19\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:19</a> (cf. Ex 19:16); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:10</a>; 4:1; 8:2, 6, 13; 9:14; D 16:6; EpilMosq 4. <span class=\"greek\">μετὰ</span> <span class=\"greek\">σάλπιγγος</span> <span class=\"greek\">φωνῆς</span> <span class=\"greek\">μεγάλης</span> com uma trombeta que emite um toque forte <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:31</a> v.l. (v. <span class=\"greek\">φωνή</span> 1). <span class=\"greek\">ἤχησεν</span> <span class=\"greek\">ς</span>. <span class=\"greek\">κύριου</span> a trombeta do Senhor soou GJs 8:3 (cf. PsSol 8:1 <span class=\"greek\">φωνὴν</span> <span class=\"greek\">σάλπιγγος</span> <span class=\"greek\">ἠχούσης</span>).</p><p class=\"entry-text\">② o som produzido ou o sinal dado por uma trombeta, toque de trombeta, som de trombeta (Aristoph., Ach. 1001; X., R. Equ. 9, 11, Hipp. 3, 12; Aristot., Rhet. 3, 6; Polyb. 4, 13, 1; Ael. Aristid. 34, 22 K.=50 p. 554 D.: <span class=\"greek\">τῇ</span> <span class=\"greek\">πρώτῃ</span> <span class=\"greek\">ς</span>.; v. Pollux 4, 88f sobre seu som intenso; podia ser ouvido a uma distância de 60 estádios Diod S 17, 106, 7) <span class=\"greek\">μετὰ</span> <span class=\"greek\">σάλπιγγος</span> <span class=\"greek\">μεγάλης</span> com um forte toque de trombeta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:31</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ἐσχάτῃ</span> <span class=\"greek\">σάλπιγγι</span> ao som da última trombeta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.52\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:52</a>. <span class=\"greek\">ἐν</span> <span class=\"greek\">σάλπιγγι</span> <span class=\"greek\">θεοῦ</span> (<span class=\"greek\">καταβήσεται</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">οὐρανοῦ</span>) ao toque da trombeta tocada por ordem de Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.4.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 4:16</a>.—PKrentz, The Salpinx in Gk. Warfare, in Hoplites, The Classical Gk. Battle Experience, ed. VHanson ’91; JHale/MTunnell, ClBull 72, ’96, 118–24. Para lit. adicional, v. ISBE III 449; TRE XXIII 455 (instrumentos musicais de Israel).—DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαλπίζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαλπίζω</span> (<span class=\"greek\">σάλπιγξ</span>; Hom. et al.; LXX; PsSol 11:1; ParJer 4:2; ApcEsdr 4:36; ApcMos; Philo, Spec. Leg. 2, 188; Jos., Ant. 5, 23) fut. <span class=\"greek\">σαλπίσω</span> (Lob. sobre Phryn. p. 191); 1 aor. <span class=\"greek\">ἐσάλπισα</span> (Aelian, VH 1, 26; LXX; Jos., Ant. 7, 279.—Sobre ambas as formas v. B-D-F §71; Mlt-H. 257)</p><p class=\"entry-text\">① produzir o som de uma trombeta, tocar trombeta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:6</a>–13; 9:1, 13; 10:7; 11:15.—Impess. (X., An. 1, 2, 17) <span class=\"greek\">σαλπίσει</span> a trombeta soará <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.52\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:52</a> (B-D-F §129; Rob. 392).</p><p class=\"entry-text\">② divulgar algo com alarde, apregoar. <span class=\"greek\">ς</span>. provavelmente deve ser entendido metaf. (cf. Ps.-Lucian, Ocypus v. 114 <span class=\"greek\">ἀλέκτωρ</span> <span class=\"greek\">ἡμέραν</span> <span class=\"greek\">ἐσάλπισεν</span>; Achilles Tat. 8, 10, 10 <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">σάλπιγγι</span> … <span class=\"greek\">μοιχεύεται</span>=divulga publicamente seu adultério; Synesius, To Paeonius 1 p. 308a <span class=\"greek\">τὸ</span> <span class=\"greek\">κηρύττειν</span> <span class=\"greek\">ἑαυτὸν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">ποιεῖν</span> <span class=\"greek\">ὑπὲρ</span> <span class=\"greek\">ἐπιδείξεως</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">σοφίας</span> <span class=\"greek\">ἀλλὰ</span> <span class=\"greek\">σοφιστείας</span> <span class=\"greek\">ἐστί</span>=alardear os próprios feitos e fazer tudo em função da publicidade não é próprio da sabedoria, mas da inteligência mal empregada; cf. M. Ant. 5, 6 <span class=\"greek\">ἄνθρωπος</span> <span class=\"greek\">εὖ</span> <span class=\"greek\">ποιήσας</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπιβοᾶται</span>=quem faz uma boa ação não a divulga) em <span class=\"greek\">μὴ</span> <span class=\"greek\">σαλπίσῃς</span> <span class=\"greek\">ἔμπροσθέν</span> <span class=\"greek\">σου</span> não deves tocar trombeta diante de ti <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 6:2</a> (interpretação diversa em EKlostermann ad loc.; ABüchler, JTS 10, 1909, 266ff. V. Betz, SM 355–58.).—DELG s.v. <span class=\"greek\">σάλπιγξ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">σαλπιστής, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">σαλπιστής</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (v. os dois verbetes precedentes; forma posterior em lugar da mais antiga <span class=\"greek\">σαλπι</span>(<span class=\"greek\">γ</span>)<span class=\"greek\">κτής</span>.—Theophr., Char. 25; Polyb. 1, 45, 13; Dionys. Hal. 4, 17, 3; 4, 18, 3; Chariton 8, 2, 6 al.; SIG 1058, 4; 1059 II, 20; Sb 4591, 3.—WRutherford, The New Phrynichus 1881, 279; Lob., Phryn. 191f) trombeteiro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.22\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:22</a>.—DELG s.v. <span class=\"greek\">σάλπιγξ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλώμη, ης, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαλώμη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (SEG VIII, 197 [I d.C.; Jerusalém]; Joseph. índice e v. B-D-F §53, 3; Mlt-H. 144) Salomé, uma das várias mulheres galileias que seguiam Jesus, <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:40</a>; 16:1; GJs 19:3; 20:1, 2 (códices); 3:4 (códices); caso seja lícito combinar <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.15.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 15:40</a> com seu paralelo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.27.56\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 27:56</a>, onde o nome não ocorre, ela era a esposa de Zebedeu e mãe de Tiago e João. (A filha de Herodias mencionada, mas não nomeada em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.14.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 14:6</a>ff [sobre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 6:22</a>–24 v. <span class=\"greek\">Ἡρῳδίας</span>], também se chamava Salomé, cf. Jos., Ant. 18, 136.—HDaffner, Salome, 1912; WSpeyer, D. Tod der Salome, Ac 10, ’67, 176–80; RGundry, Mark ’93, 320f.)—Kl. Pauly IV 1520; BHHW III, 1650f.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαλωμών</h1><div class=\"entry-meta\"><span>variante de nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαλωμών</span> (LXX; v. Thackeray 165; papiro mágico cristão: PGM II, P 17, 10 p. 226 [Henrichs]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.47\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:47</a> Tdf.; v. <span class=\"greek\">Σολομών</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαμάρεια, ας, ἡ</h1><div class=\"entry-meta\"><span>nome próprio feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαμάρεια</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (deve ser grafada e acentuada por analogia com <span class=\"greek\">Ἀλεξάνδρεια</span> etc.; v. B-D-F §38, mas também Rob. 197; Mlt-H. 147) Samaria (a forma grega do nome em Polyb. 5, 71, 11; Strabo 16, 2, 34; Diod S 19, 93, 7; Pliny 5, 13, 17; LXX; ParJer 8:11; AscIs; Joseph. índice), originalmente o nome da cidade (hebr. <span class=\"hebrew\">שֹׁמְרוֹן</span>, aram. <span class=\"hebrew\">שָׁמְרַיִן</span>), embora não com esse sentido em nossa lit., depois transferido para toda a província que, na época do NT, abrangia a região desde a planície de Jezreel para o sul até a fronteira da Judeia. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:4</a> (Jos., Vi. 269 <span class=\"greek\">ἔδει</span> <span class=\"greek\">δι</span>’ <span class=\"greek\">ἐκείνης</span> [=<span class=\"greek\">τ</span>. <span class=\"greek\">Σαμαρείας</span>] <span class=\"greek\">πορεύεσθαι</span>, Ant. 20, 118); 4:5; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:9</a>, 14. Com a Judeia 1:8; 8:1; com a Judeia e a Galileia 9:31; com a Galileia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:11</a>; com a Fenícia <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 15:3</a>. <span class=\"greek\">γυνὴ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Σαμαρείας</span> uma mulher samaritana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:7</a>. <span class=\"greek\">ἡ</span> <span class=\"greek\">πόλις</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">Σαμαρείας</span> a cidade (principal) de Samaria (v. <span class=\"greek\">πόλις</span> 1), isto é, a cidade de Samaria que, desde o tempo de Herodes, o Grande, era conhecida como Sebaste <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:5</a> (sobre isso v. JBoehmer, ZNW 9, 1908, 216–18).—GHölscher, Palästina in der persischen u. hellenist. Zeit 1903; Baedeker, Palästina u. Syrien7 1910; HGuthe, RE XVII 1906, 419ff; XXIV 1913, 448f; Schürer índice, v. esp. II 16f n. 50; LHaefeli, Gesch. der Landschaft Sam. von 722 b.c. bis 67 a.d. 1922; AParrot, Samaria, trad. SHooke, ’58.—Kl. Pauly IV 1529f; BHHW III 1655–60; OEANE II 463–67; TRE XXIX, 744–50.—M-M. DBS XI, 740–56. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαμαρία</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαμαρία</span> v. <span class=\"greek\">Σαμάρεια</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαμαρίτης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαμαρίτης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (também <span class=\"greek\">Σαμαρείτης</span>; <span class=\"greek\">Σαμαριτάνος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:5</a> D [talvez influenciado pelo latim].—Joseph. índice; Damasc., Vi. Isid. 141. Para a grafia v. B-D-F §38; Rob. 197.—Stephan. Byz. s.v. <span class=\"greek\">Ὠρεός</span> exige <span class=\"greek\">Σαμαρείτης</span> e remete s.v. <span class=\"greek\">Σαμάρεια</span> a certo Antíoco como autoridade.—Appian, Bell. Civ. 5, 75 §319 tem, como Just., a forma <span class=\"greek\">Σαμαρεύς</span>,-<span class=\"greek\">έως</span>: <span class=\"greek\">Ἰδουμαίων</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">Σαμαρέων</span>) samaritano (masc.) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:16</a>. Personagem principal de uma história (sobre isso EBuonaiuti, Religio 11, ’35, 117–25; JGordon, ET 56, ’45, 302–4; FLeenhardt, Aux sources de la tradition chrétienne [MGoguel Festschr.] ’50, 132–38; BGerhardsson, ConNeot 16, ’58; JDerrett, Law in the NT, ’70, 208–27; DHamm, CBQ 56, ’94, 273–87; v. <span class=\"greek\">παραβολή</span> 2a, final) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.10.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 10:33</a>. Pl. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:39</a>f. Evitados pelos judeus v. 9 (v. <span class=\"greek\">συγχράομαι</span>; cf. Sir 50:25f; Jos., Ant. 18, 30; 20, 118, Bell. 2, 232f; mas Just. A I, 53, 3f associa judeus e samaritanos em contraste com as ‘nações’; v. Schürer II 19f sobre a relação com Israel), também desprezados por eles 8:48. <span class=\"greek\">πόλις</span> <span class=\"greek\">Σαμαριτῶν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.5\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:5</a>; <span class=\"greek\">κώμη</span> <span class=\"greek\">Σ</span>. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.52\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:52</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.25\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 8:25</a>.—Lit. s.v. <span class=\"greek\">Σαμάρεια</span>, também EKautzsch, RE XVII 1906, 428ff; JMontgomery, The Samaritans 1907; JEHThomson, The Samaritans 1919; MGaster, The Samaritans 1925; Lightley (<span class=\"greek\">Σαδδουκαῖος</span>, final); Billerb. I 538–60; KBornhäuser, ZST 9, ’32, 552–66; JJeremias, Jerusalem z. Zeit Jesu II B 1929–37, 224ff: Die Samaritaner; MEnslin, Lk and the Samaritans: HTR 36, ’43, 278–97; JBowman, Samaritan Studies: BJRL 40, ’58, 298–329; ACrown/RPlummer/ATal, eds., A Companion to Samaritan Studies ’93; ACrown, A Bibliography of the Samaritans ’93; Schürer índice.—RE XVII 428ff; DBS XI 740–56; BHHW III 1660f; OEANE IV 468–72; TRE XXIX 750–56. Sobre inscr. samaritanas v. New Docs 1, 110; 5, 138; Boffo, Iscrizioni 47–60 (lit.).—M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0318-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Σαμαρῖτις, ιδος, ἡ</h1><div class=\"entry-meta\"><span>adjetivo e substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Σαμαρῖτις</span>, <span class=\"greek\">ιδος</span>, <span class=\"greek\">ἡ</span> (também <span class=\"greek\">Σαμαρεῖτις</span>; 1 Macc 10:30; 11:28; EpArist 107; Jos., Bell. 3, 48 al.; IG III, 2892) fem. de <span class=\"greek\">Σαμαρίτης</span>, adj. e subst., samaritana <span class=\"greek\">ἡ</span> <span class=\"greek\">γυνὴ</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">Σαμαρῖτις</span> a mulher samaritana <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.9\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:9</a>a; cf. 9b.—TW.</p></section></article>"};
